[CmdletBinding()]param()
$ErrorActionPreference='Stop';$root=[IO.Path]::GetFullPath((Join-Path $PSScriptRoot '..'));$tmp=Join-Path ([IO.Path]::GetTempPath()) ('story-neg-'+[guid]::NewGuid().ToString('N'));try{& powershell -NoProfile -ExecutionPolicy Bypass -File (Join-Path $root 'automation\New-SyntheticProjectStory.ps1') -Destination $tmp|Out-Null;$x=Get-Content (Join-Path $tmp 'project-story.json') -Raw|ConvertFrom-Json;$x.tickets[0].comments=@();$x|ConvertTo-Json -Depth 20|Set-Content (Join-Path $tmp 'project-story.json');& powershell -NoProfile -ExecutionPolicy Bypass -File (Join-Path $root 'automation\Test-SyntheticProjectStory.ps1') -Path $tmp|Out-Null;if($LASTEXITCODE -eq 0){throw 'STORY_DONE_WITHOUT_COMMENT_ACCEPTED'};Write-Host 'PASS: Ticket closure negative gate.'}finally{if(Test-Path $tmp){Remove-Item $tmp -Recurse -Force -ErrorAction SilentlyContinue}}
